// pb_hooks/delete_household_tasks.pb.js
// Deletes ALL automatically generated household tasks (cleaning/tidying/taking out the bins).
// Self-created tasks stay untouched.
// NEW: tasks live in the PocketBase collection "aufgaben" (pinn-aufgaben.js), no longer in the
// Apple tasks calendar. The previous calendar variant is commented out below.

routerAdd("POST", "/api/delete-household-tasks", (e) => {
    try {
        const deletedCount = require(`${__hooks}/pinn-aufgaben.js`).deleteHouseholdTasks(e.auth.getString("familie"));
        return e.json(200, { success: true, deletedCount: deletedCount });
    } catch (err) {
        return e.json(200, { error: err.message });
    }
}, $apis.requireAuth("benutzer"));

/* ===== COMMENTED OUT: previous variant via the Apple tasks calendar =====
// pb_hooks/delete_household_tasks.pb.js
// Deletes ALL tasks automatically generated by the household feature (cleanings/tidying/
// taking out the bins) from the tasks calendar. Normal, manually created tasks stay
// untouched - they are recognised by the title prefix (category name + ":" or the fixed
// "🗑️ Mülleimer rausbringen:" prefix).
// Apple credentials come from the .env (calendarSync.loadAppleConfig), not from familien_daten.

routerAdd("POST", "/api/delete-household-tasks", (e) => {
    try {
        const calendarSync = require(`${__hooks}/calendar-sync.js`);
        const { data, config, configured } = calendarSync.loadAppleConfig();

        if (!configured) {
            return e.json(200, { error: calendarSync.MISSING_CREDENTIALS_MESSAGE });
        }
        if (!config.taskCalendarName) {
            return e.json(200, { error: "Kein Aufgaben-Kalender eingerichtet." });
        }

        const deletedCount = calendarSync.deleteHouseholdTasks(config.email, config.appPassword, config.taskCalendarName, data.cleaningCategories || []);
        calendarSync.syncCalendarFileOnly(); // only update the calendar file - NO household detection (otherwise the tasks that were just deleted come right back)
        return e.json(200, { success: true, deletedCount: deletedCount });
    } catch (err) {
        return e.json(200, { error: err.message });
    }
}, $apis.requireAuth("benutzer"));
===== END COMMENTED OUT ===== */
